"""FastAPI dashboard server for hosting AutoHeal-AI reports and live metrics."""

from pathlib import Path
from fastapi import FastAPI
from fastapi.responses import HTMLResponse, FileResponse
from fastapi.staticfiles import StaticFiles

app = FastAPI(title="AutoHeal-AI Monitoring Dashboard")
ARTIFACTS_DIR = Path("artifacts")


@app.get("/", response_class=HTMLResponse)
async def view_dashboard():
    """Serve the latest HTML report generated by AutoHeal-AI."""
    report_file = ARTIFACTS_DIR / "report.html"
    if report_file.exists():
        with open(report_file, "r", encoding="utf-8") as f:
            return HTMLResponse(content=f.read())
    return HTMLResponse(
        content="<h3>No report generated yet. Run: <code>python -m autoheal.cli demo</code></h3>",
        status_code=404
    )


@app.get("/patch", response_class=FileResponse)
async def download_patch():
    """Download the suggested selector diff patch file."""
    patch_file = ARTIFACTS_DIR / "suggested_selector_patch.diff"
    if patch_file.exists():
        return FileResponse(patch_file, media_type="text/plain", filename="suggested_selector_patch.diff")
    return HTMLResponse("Patch file not found", status_code=404)
